PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT NOT NULL COLLATE NOCASE UNIQUE, password TEXT NOT NULL, role TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,sku TEXT NOT NULL COLLATE NOCASE UNIQUE,name TEXT NOT NULL,category TEXT NOT NULL,brand TEXT NOT NULL,size TEXT NOT NULL,description TEXT NOT NULL,reorder INTEGER NOT NULL,units TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS contacts(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL,category TEXT NOT NULL,credit INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS docs(
 id INTEGER PRIMARY KEY,kind TEXT NOT NULL,day TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES users,
 party INTEGER REFERENCES contacts,reference TEXT NOT NULL,channel TEXT NOT NULL,currency TEXT NOT NULL,rate INTEGER NOT NULL,
 total INTEGER NOT NULL DEFAULT 0,base INTEGER NOT NULL DEFAULT 0,tax INTEGER NOT NULL DEFAULT 0,cost INTEGER NOT NULL DEFAULT 0,
 tax_entered INTEGER NOT NULL DEFAULT 0,discount INTEGER NOT NULL DEFAULT 0,freight INTEGER NOT NULL DEFAULT 0,
 due TEXT NOT NULL,note TEXT NOT NULL,linked INTEGER REFERENCES docs,created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS docs_kind_day ON docs(kind,day);
CREATE INDEX IF NOT EXISTS docs_linked ON docs(linked);
CREATE UNIQUE INDEX IF NOT EXISTS purchase_reference ON docs(party,reference COLLATE NOCASE)
 WHERE kind='purchase' AND reference<>'';
CREATE TABLE IF NOT EXISTS lines(
 id INTEGER PRIMARY KEY,doc INTEGER NOT NULL REFERENCES docs,product INTEGER NOT NULL REFERENCES products,label TEXT NOT NULL,
 sku TEXT NOT NULL,unit TEXT NOT NULL,factor INTEGER NOT NULL,qty INTEGER NOT NULL,price INTEGER NOT NULL,
 amount INTEGER NOT NULL,base INTEGER NOT NULL,cost INTEGER NOT NULL,batch TEXT NOT NULL,expiry TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS lines_doc ON lines(doc);
CREATE TABLE IF NOT EXISTS lots(id INTEGER PRIMARY KEY,product INTEGER NOT NULL REFERENCES products,source INTEGER NOT NULL REFERENCES lines,remaining INTEGER NOT NULL CHECK(remaining>=0),value INTEGER NOT NULL CHECK(value>=0),batch TEXT NOT NULL,expiry TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS lots_product ON lots(product);
CREATE TABLE IF NOT EXISTS movements(id INTEGER PRIMARY KEY,doc INTEGER NOT NULL REFERENCES docs,line INTEGER NOT NULL REFERENCES lines,lot INTEGER NOT NULL REFERENCES lots,quantity INTEGER NOT NULL,value INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS movements_lot ON movements(lot,doc);
CREATE INDEX IF NOT EXISTS movements_doc ON movements(doc);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,doc INTEGER NOT NULL REFERENCES docs,day TEXT NOT NULL,method TEXT NOT NULL,amount INTEGER NOT NULL,base INTEGER NOT NULL,user_id INTEGER NOT NULL REFERENCES users);
CREATE INDEX IF NOT EXISTS payments_doc ON payments(doc);
CREATE TABLE IF NOT EXISTS counts(id INTEGER PRIMARY KEY,day TEXT NOT NULL,method TEXT NOT NULL,currency TEXT NOT NULL,actual INTEGER NOT NULL,expected INTEGER NOT NULL,note TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES users,UNIQUE(day,method,currency));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users,event TEXT NOT NULL,target TEXT NOT NULL,created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS requests(user_id INTEGER NOT NULL REFERENCES users,key TEXT NOT NULL,hash TEXT NOT NULL,response TEXT NOT NULL,PRIMARY KEY(user_id,key));
